{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C43"],
      "claim": "Propylthiouracil, which shares the thiourea (C=S) moiety, has an absolute oral bioavailability of 77 ± 13% in humans after IV comparison, showing that the thiourea group is compatible with F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Vernakalant, a basic amine-containing drug with aromatic and ether functionality, has an absolute oral bioavailability of 71 ± 21% in healthy volunteers, supporting that the query's basic amine and moderate lipophilicity are consistent with high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Suvorexant, containing a chloro-substituted heteroaromatic core, has 82% absolute oral bioavailability in humans under fasted conditions, supporting high F for the query's chloro-heteroaromatic scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Melperone, a lipophilic basic piperidine drug, has an absolute oral bioavailability of 64 ± 16.6% in healthy volunteers, indicating that basic amine-containing lipophilic molecules can achieve F well above 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Pentazocine, which shares the prenyl-on-nitrogen and tertiary amine motif, has a mean absolute oral bioavailability of 18% in healthy subjects, below the 20% threshold; however, its low F is largely attributed to a phenolic OH conjugation liability that is absent in the query, limiting transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Multiple high-transfer human absolute bioavailability measurements in structurally relevant classes (thiourea, basic amine, chloro-heteroaromatic) support F ≥ 20%, while the only clearly low analogue (pentazocine) lacks the query's thiourea and contains a phenolic metabolic liability not present in the query. The balance of direct experimental evidence favors high oral bioavailability.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability data for the query molecule.",
    "The metabolic fate of the prenyl group and thiourea in humans is not directly characterized.",
    "Potential solubility limitations from high logP are not experimentally quantified.",
    "The relevance of pentazocine's low F is uncertain because its key phenolic conjugation site is absent in the query."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C43"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "thiouracil"
    },
    {
      "applicability": "high",
      "card_ids": ["C06", "C02"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "basic amine"
    },
    {
      "applicability": "high",
      "card_ids": ["C26"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "chloro-heteroaromatic"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C17"],
      "decision_effect": "weakened",
      "direction": "contradictory",
      "family": "prenyl-amine opioid"
    }
  ],
  "revision_action": "initial"
}

